#define PI 3.14159265359

// 2D rotation matrix
mat2 rotate2d(float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return mat2(c, -s,
        s, c);
}

float drawBox(vec2 _st, vec2 _size) {
    vec2 halfSize = vec2(0.5) - _size * 0.5;
    vec2 smoothEdge = vec2(0.001); // Soft edges for anti-aliasing
    vec2 uv = smoothstep(halfSize, halfSize + smoothEdge, _st);
    uv *= smoothstep(halfSize, halfSize + smoothEdge, vec2(1.0) - _st);
    return uv.x * uv.y;
}

float drawCross(vec2 _st, float _size) {
    return drawBox(_st, vec2(_size, _size / 4.0)) + // Horizontal bar
        drawBox(_st, vec2(_size / 4.0, _size)); // Vertical bar
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 st = (2.0 * fragCoord - iResolution.xy) / iResolution.y; // Normalize coordinates
    vec3 color = vec3(1.0);

    // Rotate the space with smooth oscillation over time
    float rotationAngle = sin(iTime * 0.5) * PI; // Slower rotation
    st = rotate2d(rotationAngle) * st;

    //putting the cross back to origin
    st += vec2(0.5);

    color = mix(color, vec3(1.0, 0.0, 0.0), drawCross(st, 0.8));

    fragColor = vec4(color, 1.0);
}
